function hover(e,t){e.setAttribute("src",t)}function unhover(e,t){e.setAttribute("src",t)}function adjustCSS(){if(document.documentElement.clientHeight<720){$(".springroll .col-md-3").css("display","none");$(".springroll .col-md-9").css("width","100%");$(".springroll img").css("max-height","400px");$(".springroll img").css("margin","auto");$(".springroll .row h2").css("text-align","center");$(".footer .back-to-top").css("display","block")}else if($(".springroll .col-md-3").css("display")==="none"&&document.documentElement.clientWidth>=992){$(".springroll .col-md-3").css("display","block");$(".springroll .col-md-9").css("width","75%");$(".springroll img").css("max-height","auto");$(".springroll img").css("margin","auto");$(".springroll .row h2").css("text-align","left");$(".footer .back-to-top").css("display","none")}if(document.documentElement.clientWidth<992){$(".social-image img").unbind("mouseover mouseout");$("#facebook-logo").attr("src","./img/facebook.jpg");$("#indiegogo-logo").attr("src","./img/indiegogo.jpg")}else{$("#facebook-logo").mouseover(function(){hover(this,"./img/facebook.jpg")});$("#facebook-logo").mouseout(function(){hover(this,"./img/facebook-gs.jpg")});$("#indiegogo-logo").mouseover(function(){hover(this,"./img/indiegogo.jpg")});$("#indiegogo-logo").mouseout(function(){hover(this,"./img/indiegogo-gs.jpg")});$("#facebook-logo").attr("src","./img/facebook-gs.jpg");$("#indiegogo-logo").attr("src","./img/indiegogo-gs.jpg")}}$(window).resize(adjustCSS);$(document).ready(function(){if(window.location.hash){window.location=""}$("body").scrollspy({target:"#sidebar.spy-active",offset:280});$(".back-to-top a,a[href*=#]:not([href=#])").click(function(){if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")||location.hostname==this.hostname){var e=this;if(this.parentNode.className==="back-to-top"){this.hash="#intro";var e=$("#sidebar li:first-child")}var t=$(this.hash);t=t.length?t:$("[name="+this.hash.slice(1)+"]");if(t.length){var n=-50;if(this.hash!=="#intro"){n=t.offset().top-200;$("#sidebar")[0].top=0}var r=Math.abs($(document).scrollTop()-n),i=500;if(r>2e3){i=1e3}else if(r>1e3){i=750}$("#sidebar").removeClass("spy-active");$("body").animate({scrollTop:n},i,function(){$("#sidebar").addClass("spy-active");$("#sidebar .active").removeClass("active");$(e).closest("li").addClass("active");$("body").scrollspy("refresh")});return false}}});adjustCSS()})